(function(){
var L="data:image/png;base64,";

var N=[
  {s:'Catalogue'},
  {h:'amayaa_dashboard.html',i:'📊',l:'Dashboard'},
  {h:'amayaa_products.html',i:'🧣',l:'Products'},
  {h:'amayaa_categories.html',i:'🏷',l:'Categories'},
  {h:'amayaa_products.html?filter=offers',i:'🎁',l:'Special Offers'},{h:'amayaa_bulk_upload.html',i:'📤',l:'Bulk Upload'},
  {s:'Content'},
  {h:'amayaa_banners.html',i:'🖼',l:'Banner'},
  {h:'amayaa_blog.html',i:'📝',l:'Blog Posts'},
  {h:'amayaa_about.html',i:'📖',l:'Our Story'},{h:'amayaa_faq.html',i:'❓',l:'FAQ'},{h:'amayaa_policies.html',i:'📋',l:'Policies & T\u0026C'},{h:'amayaa_content_library.html',i:'📚',l:'Content Library'},
  {s:'System'},
  {h:'amayaa_settings.html',i:'⚙',l:'Site Settings'},
  {h:'amayaa_typography.html',i:'🔤',l:'Typography'},
  {h:'amayaa_audit.html',i:'📋',l:'Audit Trail'},
  {h:'https://amayaa.goatcounter.com',i:'📈',l:'Analytics',t:'_blank'},
  {h:'/index.html',i:'🌐',l:'View Website',t:'_blank'}
];

function active(href){
  var cur=window.location.pathname.split('/').pop()+window.location.search;
  var curBase=window.location.pathname.split('/').pop();
  var hrefBase=href.split('?')[0];
  if(href===cur||hrefBase===curBase) return true;
  if(href.includes('?')&&curBase===hrefBase&&window.location.search.includes(href.split('?')[1])) return true;
  return false;
}

function build(){
  var h='<div class="sb-brand">';
  h+='<img class="sb-logo-img" src="'+L+'" alt="Amayaa logo" style=\"width:44px;height:44px;flex-shrink:0;\">';
  h+='<div class="sb-text"><div class="sb-name">Amayaa</div>';
  h+='<div class="sb-sub">Admin Panel</div></div></div>';
  h+='<nav class="sb-nav">';
  N.forEach(function(item){
    if(item.s){h+='<div class="sb-section">'+item.s+'</div>';return;}
    var cls='sb-link'+(active(item.h)?' active':'');
    var tgt=item.t?' target="'+item.t+'"':'';
    h+='<a href="'+item.h+'" class="'+cls+'"'+tgt+'>';
    h+='<span class="sb-icon">'+item.i+'</span>'+item.l+'</a>';
  });
  h+='</nav>';
  h+='<div class="sb-footer">';
  h+='<button class="sb-logout" onclick="sessionStorage.removeItem(\'amayaa_admin\');window.location.href=\'index.html\'">';
  h+='🚪 Log Out</button></div>';
  return h;
}

function inject(){
  var el=document.querySelector('aside.sidebar');
  if(!el) return;
  el.innerHTML=build();
}

if(document.readyState==='loading'){
  document.addEventListener('DOMContentLoaded',inject);
}else{inject();}
})();
